1	import 'dart:async';
2	
3	import 'package:desktop_multi_window/desktop_multi_window.dart';
4	import 'package:flutter/foundation.dart';
5	import 'package:flutter/services.dart';
6	
7	import '../capabilities/app_capabilities.dart';
8	import '../capabilities/capability_rpc.dart';
9	import 'app_window_appearance.dart';
10	
11	abstract final class AppWindowRpcProtocol {
12	  static const channelName = 'gopeed.app.capabilities.v1';
13	  static const call = 'capability.call';
14	  static const bootstrap = 'window.bootstrap';
15	  static const subscribe = 'window.subscribe';
16	  static const unsubscribe = 'window.unsubscribe';
17	  static const event = 'window.event';
18	  static const appearanceChanged = 'appearance.changed';
19	}
20	
21	const _hostChannel = WindowMethodChannel(AppWindowRpcProtocol.channelName, mode: ChannelMode.unidirectional);
22	
23	class WindowCapabilityInvoker implements CapabilityInvoker {
24	  const WindowCapabilityInvoker(this.codecs);
25	
26	  final RpcCodecRegistry codecs;
27	
28	  @override
29	  Future<R> invoke<P, R>(RpcMethod<P, R> method, P params) async {
30	    final raw = await _hostChannel.invokeMethod<dynamic>(AppWindowRpcProtocol.call, {
31	      'operation': method.name,
32	      'payload': codecs.encode(params),
33	    });
34	    final response = codecs.decode<Map<String, dynamic>>(raw);
35	    if (response['ok'] != true) {
36	      final error = codecs.decode<Map<String, dynamic>>(response['error']);
37	      throw CapabilityException(
38	        (error['code'] ?? 'remote_error').toString(),
39	        (error['message'] ?? 'Remote capability failed').toString(),
40	        error['details'],
41	      );
42	    }
43	    return codecs.decode<R>(response['data']);
44	  }
45	}
46	
47	class AppWindowCapabilityHost {
48	  AppWindowCapabilityHost._();
49	
50	  static final instance = AppWindowCapabilityHost._();
51	
52	  CapabilityRegistry? _registry;
53	  AppWindowAppearance _appearance = const AppWindowAppearance.defaults();
54	  final Map<String, WindowController> _subscribers = {};
55	  StreamSubscription<void>? _windowsChanged;
56	
57	  bool get started => _registry != null;
58	
59	  Future<void> start(CapabilityRegistry registry) async {
60	    if (_registry != null) return;
61	    _registry = registry;
62	    await _hostChannel.setMethodCallHandler(_handleCall);
63	    _windowsChanged = onWindowsChanged.listen((_) => unawaited(_removeClosedSubscribers()));
64	  }
65	
66	  Future<void> stop() async {
67	    _registry = null;
68	    await _windowsChanged?.cancel();
69	    _windowsChanged = null;
70	    _subscribers.clear();
71	    await _hostChannel.setMethodCallHandler(null);
72	  }
73	
74	  Future<void> _removeClosedSubscribers() async {
75	    // Engine shutdown does not run Widget.dispose, so a closed child cannot
76	    // always send window.unsubscribe itself.
77	    final registry = _registry;
78	    final candidates = _subscribers.keys.toSet();
79	    if (registry == null || candidates.isEmpty) return;
80	    try {
81	      final windows = await WindowController.getAll();
82	      if (!identical(registry, _registry)) return;
83	      final openIds = windows.map((window) => window.windowId).toSet();
84	      _subscribers.removeWhere((id, _) => candidates.contains(id) && !openIds.contains(id));
85	    } catch (_) {
86	      // The native window registry can already be gone during app shutdown.
87	    }
88	  }
89	
90	  void updateAppearance(AppWindowAppearance appearance) {
91	    if (_appearance == appearance) return;
92	    _appearance = appearance;
93	    unawaited(_broadcastAppearance());
94	  }
95	
96	  Future<dynamic> _handleCall(MethodCall call) async {
97	    try {
98	      switch (call.method) {
99	        case AppWindowRpcProtocol.call:
100	          final args = _map(call.arguments);
101	          final registry = _registry;
102	          if (registry == null) {
103	            throw const CapabilityException('host_unavailable', 'Main window capabilities are not ready');
104	          }
105	          final data = await registry.invoke((args['operation'] ?? '').toString(), args['payload']);
106	          return {'ok': true, 'data': data};
107	        case AppWindowRpcProtocol.bootstrap:
108	          return _appearance.toJson();
109	        case AppWindowRpcProtocol.subscribe:
110	          final windowId = (_map(call.arguments)['windowId'] ?? '').toString();
111	          if (windowId.isEmpty) {
112	            throw const CapabilityException('invalid_window', 'Missing child window id');
113	          }
114	          final controller = WindowController.fromWindowId(windowId);
115	          _subscribers[windowId] = controller;
116	          scheduleMicrotask(() => _sendAppearance(windowId, controller));
117	          return null;
118	        case AppWindowRpcProtocol.unsubscribe:
119	          final windowId = (_map(call.arguments)['windowId'] ?? '').toString();
120	          _subscribers.remove(windowId);
121	          return null;
122	        default:
123	          throw CapabilityException('method_not_found', 'Window RPC method not found: ${call.method}');
124	      }
125	    } on CapabilityException catch (error) {
126	      if (call.method == AppWindowRpcProtocol.call) {
127	        return {
128	          'ok': false,
129	          'error': {'code': error.code, 'message': error.message, 'details': error.details},
130	        };
131	      }
132	      rethrow;
133	    } catch (error) {
134	      if (call.method == AppWindowRpcProtocol.call) {
135	        return {
136	          'ok': false,
137	          'error': {'code': 'internal_error', 'message': error.toString()},
138	        };
139	      }
140	      rethrow;
141	    }
142	  }
143	
144	  Future<void> _broadcastAppearance() async {
145	    final subscribers = Map<String, WindowController>.of(_subscribers);
146	    await Future.wait([for (final entry in subscribers.entries) _sendAppearance(entry.key, entry.value)]);
147	  }
148	
149	  Future<void> _sendAppearance(String windowId, WindowController controller) async {
150	    try {
151	      await controller.invokeMethod<void>(AppWindowRpcProtocol.event, {
152	        'name': AppWindowRpcProtocol.appearanceChanged,
153	        'data': _appearance.toJson(),
154	      });
155	    } catch (_) {
156	      _subscribers.remove(windowId);
157	    }
158	  }
159	
160	  Map<String, dynamic> _map(Object? value) {
161	    if (value is! Map) return const {};
162	    return {for (final entry in value.entries) entry.key.toString(): entry.value};
163	  }
164	}
165	
166	class ChildWindowSession {
167	  ChildWindowSession._(this.controller, this.codecs)
168	    : capabilities = AppCapabilities(WindowCapabilityInvoker(codecs)),
169	      appearance = ValueNotifier(const AppWindowAppearance.defaults());
170	
171	  static Future<ChildWindowSession> connect(WindowController controller) async {
172	    final session = ChildWindowSession._(controller, createAppCapabilityCodecs());
173	    await session._initialize();
174	    return session;
175	  }
176	
177	  final WindowController controller;
178	  final RpcCodecRegistry codecs;
179	  final AppCapabilities capabilities;
180	  final ValueNotifier<AppWindowAppearance> appearance;
181	
182	  Future<void> _initialize() async {
183	    await controller.setWindowMethodHandler(_handleWindowCall);
184	    final initial = await _hostChannel.invokeMethod<dynamic>(AppWindowRpcProtocol.bootstrap);
185	    appearance.value = codecs.decode<AppWindowAppearance>(initial);
186	    await _hostChannel.invokeMethod<void>(AppWindowRpcProtocol.subscribe, {'windowId': controller.windowId});
187	  }
188	
189	  Future<dynamic> _handleWindowCall(MethodCall call) async {
190	    if (call.method != AppWindowRpcProtocol.event) return null;
191	    final args = codecs.decode<Map<String, dynamic>>(call.arguments);
192	    if (args['name'] == AppWindowRpcProtocol.appearanceChanged) {
193	      appearance.value = codecs.decode<AppWindowAppearance>(args['data']);
194	    }
195	    return null;
196	  }
197	
198	  void dispose() {
199	    unawaited(controller.setWindowMethodHandler(null));
200	    unawaited(_hostChannel.invokeMethod<void>(AppWindowRpcProtocol.unsubscribe, {'windowId': controller.windowId}));
201	    appearance.dispose();
202	  }
203	}
