38	    if (!isBt &&
39	        (!isFtp || result?.res.name.trim().isEmpty == true) &&
40	        result?.id.isNotEmpty == true &&
41	        files.length == 1 &&
42	        files.single.name.isNotEmpty) {
43	      return files.single.name;
44	    }
45	    if (result?.res.name.trim().isNotEmpty == true) return result!.res.name;
46	    return request.url;
47	  }
