49	  List<FileInfo> get files => result?.res.files ?? const [];
50	  bool get hasSelection => !created && result != null && selected.isNotEmpty;
51	
52	  Future<void> resolve(GopeedService service) async {
53	    if (result != null || resolving) return;
54	    resolving = true;
55	    resolveError = null;
56	    try {
57	      result = await service.resolve(ResolveTask(req: request));
58	      selected.addAll(List.generate(files.isEmpty ? 1 : files.length, (index) => index));
59	    } catch (error) {
60	      resolveError = error.toString();
61	    } finally {
62	      resolving = false;
63	    }
64	  }
