98	      member.size = httpUrl.hasMatch(req.url) ? file.size : 0;
99	      if (RegExp(r'^(ftps?|ftpes):', caseSensitive: false).hasMatch(req.url)) {
100	        final extra = OptsExtraFtp.fromJson(Map<String, dynamic>.from(member.extra as Map? ?? const {}));
101	        extra.connections = extra.connections.clamp(0, 32);
102	        member.extra = extra.toJson();
103	      }
104	      if (indexes.length > 1) _omitChecksum(member);
105	      return CreateTaskBatchItem(req: req, opts: member);
106	    }).toList();
107	  }
