114	/// A successful response completes the entire batch, including partial success.
115	class DownloadSubmission {
116	  DownloadSubmission({required this.sources, required this.request});
117	
118	  final List<PendingDownload> sources;
119	  final CreateTaskBatch request;
120	
121	  Future<void> submit(GopeedService service) async {
122	    for (final source in sources) {
123	      source.createError = null;
124	    }
125	    try {
126	      await service.createTaskBatch(request);
127	      for (final source in sources) {
128	        source.created = true;
129	      }
130	    } catch (error) {
131	      for (final source in sources) {
132	        source.createError = error.toString();
133	      }
134	    }
135	  }
136	}
