11	/// IDs identify sources within one preview and are never sent as group IDs.
12	class PendingDownload {
13	  PendingDownload({required this.id, required this.request, required this.options});
14	
15	  final String id;
16	  final Request request;
17	  final Options options;
18	  ResolveResult? result;
19	  String? resolveError;
20	  String? createError;
21	  final Set<int> selected = {};
22	  bool created = false;
23	  bool resolving = false;
24	
25	  bool get loading => result == null && resolveError == null;
26	  bool get isGroup => result != null && result!.id.isEmpty && result!.res.name.trim().isNotEmpty && files.length > 1;
27	  bool get isFtp => RegExp(r'^(ftps?|ftpes):', caseSensitive: false).hasMatch(request.url.trim());
28	  bool get isBt {
29	    if (result?.id.isEmpty == true) return false;
30	    final url = request.url.trim().toLowerCase();
31	    if (url.startsWith('http:') || url.startsWith('https:') || isFtp) return false;
32	    return url.startsWith('magnet:') ||
33	        url.startsWith('data:application/x-bittorrent;base64,') ||
34	        url.split(RegExp(r'[?#]')).first.endsWith('.torrent');
35	  }
36	
37	  String get name {
38	    if (!isBt &&
39	        (!isFtp || result?.res.name.trim().isEmpty == true) &&
40	        result?.id.isNotEmpty == true &&
41	        files.length == 1 &&
42	        files.single.name.isNotEmpty) {
43	      return files.single.name;
44	    }
45	    if (result?.res.name.trim().isNotEmpty == true) return result!.res.name;
46	    return request.url;
47	  }
48	
49	  List<FileInfo> get files => result?.res.files ?? const [];
50	  bool get hasSelection => !created && result != null && selected.isNotEmpty;
51	
52	  Future<void> resolve(GopeedService service) async {
53	    if (result != null || resolving) return;
54	    resolving = true;
55	    resolveError = null;
56	    try {
57	      result = await service.resolve(ResolveTask(req: request));
58	      selected.addAll(List.generate(files.isEmpty ? 1 : files.length, (index) => index));
59	    } catch (error) {
60	      resolveError = error.toString();
61	    } finally {
62	      resolving = false;
63	    }
64	  }
65	
66	  List<CreateTaskBatchItem> creationItems() {
67	    final indexes = selected.toList()..sort();
68	    if (result!.id.isNotEmpty || files.isEmpty) {
69	      final opts = Options.fromJson(options.toJson());
70	      if (files.isNotEmpty) opts.selectFiles = indexes;
71	      if (indexes.length > 1) _omitChecksum(opts);
72	      return [
73	        CreateTaskBatchItem(
74	          rid: result!.id.isEmpty ? null : result!.id,
75	          req: result!.id.isEmpty ? request : null,
76	          opts: opts,
77	        ),
78	      ];
79	    }
80	    final group = isGroup;
81	    final resourceName = result!.res.name;
82	    final parentSegments = [
83	      if (!group && options.path.isNotEmpty) options.path,
84	      if (!group && resourceName.trim().isNotEmpty) resourceName,
85	    ];
86	    final skipAutoCategorize = options.skipAutoCategorize || resourceName.isNotEmpty || files.length > 1;
87	    final httpUrl = RegExp(r'^https?:', caseSensitive: false);
88	    return indexes.map((index) {
89	      final file = files[index];
90	      final member = Options.fromJson(options.toJson());
91	      member.name = files.length == 1 && options.name.isNotEmpty ? options.name : file.name;
92	      final segments = [...parentSegments, if (file.path.isNotEmpty) file.path];
93	      member.path = segments.isEmpty ? '' : path.joinAll(segments);
94	      // The selected parent directory is persisted separately from members.
95	      member.asDefaultPath = false;
96	      member.skipAutoCategorize = skipAutoCategorize;
97	      final req = file.req ?? request;
98	      member.size = httpUrl.hasMatch(req.url) ? file.size : 0;
99	      if (RegExp(r'^(ftps?|ftpes):', caseSensitive: false).hasMatch(req.url)) {
100	        final extra = OptsExtraFtp.fromJson(Map<String, dynamic>.from(member.extra as Map? ?? const {}));
101	        extra.connections = extra.connections.clamp(0, 32);
102	        member.extra = extra.toJson();
103	      }
104	      if (indexes.length > 1) _omitChecksum(member);
105	      return CreateTaskBatchItem(req: req, opts: member);
106	    }).toList();
107	  }
108	
109	  void _omitChecksum(Options opts) {
110	    if (opts.extra is Map) opts.extra = Map<String, dynamic>.from(opts.extra! as Map)..remove('checksum');
111	  }
112	}
