138	List<DownloadSubmission> planDownloads(List<PendingDownload> sources) {
139	  final groups = <DownloadSubmission>[];
140	  final independent = <PendingDownload>[];
141	  for (final source in sources.where((source) => source.hasSelection)) {
142	    if (source.isGroup) {
143	      groups.add(
144	        DownloadSubmission(
145	          sources: [source],
146	          request: CreateTaskBatch(
147	            group: true,
148	            groupName: source.options.name.isNotEmpty ? source.options.name : source.result!.res.name.trim(),
149	            opts: source.options,
150	            reqs: source.creationItems(),
151	          ),
152	        ),
153	      );
154	    } else {
155	      independent.add(source);
156	    }
157	  }
158	  return [
159	    ...groups,
160	    if (independent.isNotEmpty)
161	      DownloadSubmission(
162	        sources: independent,
163	        request: CreateTaskBatch(reqs: [for (final source in independent) ...source.creationItems()]),
164	      ),
165	  ];
