30	class AppRouter {
31	  static final GlobalKey<NavigatorState> rootNavigatorKey = GlobalKey<NavigatorState>();
32	
33	  static bool get _isMobile =>
34	      !kIsWeb && (defaultTargetPlatform == TargetPlatform.android || defaultTargetPlatform == TargetPlatform.iOS);
35	
36	  static Future<void> openCreateTask({CreateTask? createTask}) =>
37	      openWindow(AppWindowPayload.createTask(createTask: createTask?.toJson()));
38	
39	  /// Opens a desktop child window, a Web modal, or a native mobile page.
40	  /// Callers never need to choose a presentation or implement a fallback.
41	  static Future<void> openWindow(AppWindowPayload payload) async {
42	    final location = AppWindowContent.location(payload.type);
43	    if (AppWindowChrome.isDesktopWindow && await AppWindowLauncher.open(payload)) return;
44	    final context = rootNavigatorKey.currentContext;
45	    if (context == null || !context.mounted) return;
46	    final router = GoRouter.of(context);
47	    if (router.state.uri.path == location) {
48	      // Native share intents may arrive while the creation page is already open.
49	      if (payload.type == AppWindowType.createTask && payload.createTask != null) {
50	        ProviderScope.containerOf(
51	          context,
52	          listen: false,
53	        ).read(pendingCreateTaskProvider.notifier).set(CreateTask.fromJson(payload.createTask!));
54	      }
55	      return;
56	    }
57	    if (_isMobile) {
58	      router.go(location, extra: payload.toRaw());
59	    } else {
60	      unawaited(router.push<void>(location, extra: payload.toRaw()));
61	    }
62	  }
63	
64	  static void showDownloadingTasks() {
65	    final context = rootNavigatorKey.currentContext;
66	    if (context == null || !context.mounted) return;
67	    ProviderScope.containerOf(context, listen: false).read(taskListNavigationProvider.notifier).showDownloading();
68	    GoRouter.of(context).go('/');
69	  }
70	
71	  static GoRouter build(WebAuthController webAuthController) {
72	    // Keep desktop and web sections as peers; native mobile retains home below them.
73	    final isMobile = _isMobile;
74	    final sectionRoutes = [
75	      GoRoute(
76	        path: isMobile ? 'extensions' : '/extensions',
77	        builder: _runtimePage((context, state) => const ExtensionsPage()),
78	        routes: [
79	          GoRoute(
80	            path: ':id',
81	            builder: _runtimePage(
82	              (context, state) => ExtensionDetailsPage(
83	                extensionId: state.pathParameters['id'] ?? '',
84	                initialItem: state.extra is ExtensionListItem ? state.extra as ExtensionListItem : null,
85	              ),
86	            ),
87	          ),
88	        ],
89	      ),
90	      GoRoute(
91	        path: isMobile ? 'settings' : '/settings',
92	        builder: _runtimePage((context, state) => const SettingsPage()),
93	        routes: [
94	          GoRoute(
95	            path: ':section',
96	            builder: _runtimePage((context, state) => SettingsPage(sectionKey: state.pathParameters['section'])),
97	          ),
98	        ],
99	      ),
100	    ];
101	    return GoRouter(
102	      navigatorKey: rootNavigatorKey,
103	      refreshListenable: webAuthController,
104	      redirect: (context, state) {
105	        final onLoginPage = state.matchedLocation == '/login';
106	        if (webAuthController.loginRequired) {
107	          if (onLoginPage) return null;
108	          return Uri(path: '/login', queryParameters: {'from': state.uri.toString()}).toString();
109	        }
110	        if (onLoginPage) {
111	          return _safeReturnLocation(state.uri.queryParameters['from']);
112	        }
113	        return null;
114	      },
115	      routes: [
116	        GoRoute(path: '/login', parentNavigatorKey: rootNavigatorKey, builder: (context, state) => const LoginPage()),
117	        ShellRoute(
118	          builder: (context, state, child) => MobileExitGuard(child: MainShell(child: child)),
119	          routes: [
120	            GoRoute(
121	              path: '/',
122	              builder: _runtimePage((context, state) => const HomePage()),
123	              routes: [
124	                GoRoute(
125	                  path: 'create',
126	                  parentNavigatorKey: rootNavigatorKey,
127	                  pageBuilder: (context, state) {
128	                    final payload = state.extra is String
129	                        ? AppWindowPayload.fromRaw(state.extra! as String)
130	                        : AppWindowPayload.createTask();
131	                    final child = RuntimePage(
132	                      builder: (context) => AppWindowContent.build(
133	                        payload,
134	                        modal: !isMobile,
135	                        onClose: (created) {
136	                          if (created) {
137	                            showDownloadingTasks();
138	                          } else if (context.canPop()) {
139	                            context.pop();
140	                          } else {
141	                            context.go('/');
142	                          }
143	                        },
144	                      ),
145	                    );
146	                    return isMobile
147	                        ? NoTransitionPage<void>(key: state.pageKey, child: child)
148	                        : AppWindowPage<void>(key: state.pageKey, child: child);
149	                  },
150	                ),
151	                GoRoute(
152	                  path: 'tasks/:id',
153	                  builder: _runtimePage(
154	                    (context, state) => TaskDetailsPage(
155	                      taskId: state.pathParameters['id'] ?? '',
156	                      initialTask: state.extra is TaskRecord ? state.extra as TaskRecord : null,
157	                    ),
158	                  ),
159	                  routes: [
160	                    GoRoute(
161	                      path: 'files',
162	                      builder: _runtimePage(
163	                        (context, state) => TaskFilesPage(
164	                          taskId: state.pathParameters['id'] ?? '',
165	                          initialTask: state.extra is TaskRecord ? state.extra as TaskRecord : null,
166	                        ),
167	                      ),
168	                    ),
169	                  ],
170	                ),
171	                if (isMobile) ...sectionRoutes,
172	              ],
173	            ),
174	            if (!isMobile) ...sectionRoutes,
175	          ],
176	        ),
177	      ],
178	    );
179	  }
180	
181	  static GoRouterWidgetBuilder _runtimePage(GoRouterWidgetBuilder builder) {
182	    return (context, state) => RuntimePage(builder: (context) => builder(context, state));
183	  }
184	
185	  static String _safeReturnLocation(String? location) {
186	    if (location == null || location.isEmpty) return '/';
187	    final uri = Uri.tryParse(location);
188	    if (uri == null || uri.hasScheme || uri.host.isNotEmpty || !location.startsWith('/') || uri.path == '/login') {
189	      return '/';
190	    }
191	    return location;
192	  }
193	}
