11	  const channels = MethodChannel('mixin.one/desktop_multi_window/channels');
12	  const codec = StandardMethodCodec();
13	  final messenger = TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;
14	
15	  tearDown(() async {
16	    await AppWindowCapabilityHost.instance.stop();
17	    messenger.setMockMethodCallHandler(windows, null);
18	    messenger.setMockMethodCallHandler(channels, null);
19	  });
20	
21	  testWidgets('closed engines lose appearance subscriptions without a Dart unsubscribe', (tester) async {
22	    final deliveries = <String>[];
23	    messenger.setMockMethodCallHandler(channels, (call) async {
24	      if (call.method == 'invokeMethod') {
25	        final args = Map<String, dynamic>.from(call.arguments as Map);
26	        if (args['method'] == AppWindowRpcProtocol.event) deliveries.add(args['channel'] as String);
27	      }
28	      return null;
29	    });
30	    messenger.setMockMethodCallHandler(windows, (call) async {
31	      if (call.method == 'getAllWindows') {
32	        return [
33	          {'windowId': 'live-child', 'windowArgument': ''},
34	        ];
35	      }
36	      return null;
37	    });
38	    final host = AppWindowCapabilityHost.instance;
39	    await host.start(CapabilityRegistry(createAppCapabilityCodecs()));
40	    for (final id in ['closed-child', 'live-child']) {
41	      await messenger.handlePlatformMessage(
42	        channels.name,
43	        codec.encodeMethodCall(
44	          MethodCall('methodCall', {
45	            'channel': AppWindowRpcProtocol.channelName,
46	            'method': AppWindowRpcProtocol.subscribe,
47	            'arguments': {'windowId': id},
48	          }),
49	        ),
50	        (_) {},
51	      );
52	    }
53	    await tester.pump();
54	    deliveries.clear();
55	    await messenger.handlePlatformMessage(
56	      windows.name,
57	      codec.encodeMethodCall(const MethodCall('onWindowsChanged')),
58	      (_) {},
59	    );
60	    await tester.pump();
61	    host.updateAppearance(const AppWindowAppearance(themeMode: 'dark', themeColor: 'green', locale: 'zh'));
62	    await tester.pump();
63	    expect(deliveries, ['mixin.one/window_controller/live-child']);
64	  });
65	}
